SELECT ?p ?ts WHERE {
  ?p brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#AHU03> .
  OPTIONAL { ?p ref:hasExternalReference ?r . ?r ref:hasTimeseriesId ?ts }
}

SELECT ?p ?ts WHERE {
  ?x brick:hasPoint ?p .
  FILTER(str(?p) && "AHU03" && "Electric")
  OPTIONAL { ?p ref:hasExternalReference ?r . ?r ref:hasTimeseriesId ?ts }
}
